"""Blinded source annotation packets. No autogenerated gold labels or market accuracy."""

import json
from datetime import UTC, datetime
from pathlib import Path

from sqlalchemy import select

from engine.filing_evidence import assessment, snapshots
from engine.ingestion.contracts import digest
from engine.models.contracts import utc

CLASSES = {"ISSUER_ATTRIBUTION", "UNCERTAIN_OR_FORWARD_LOOKING", "NO_CAUSAL_CLAIM"}


def packet(conn, cutoff):
    cases, predictions, seen = [], {}, set()
    for row in conn.execute(
        select(snapshots)
        .where(snapshots.c.available_at <= cutoff)
        .order_by(snapshots.c.version.desc())
    ).mappings():
        key = (row["ticker"], row["accession"])
        if key in seen:
            continue
        seen.add(key)
        current = assessment(conn, *key, cutoff)
        if not current["segments"] and not current["attributions"]:
            continue
        # All filings of one issuer stay in one split: no amendment leakage between splits.
        split = "holdout" if row["ticker"] in {"AMD", "SNDK"} else "development"
        predicted = {x["text"]: x["status"] for x in current["attributions"]}
        paragraphs = row["payload"]["review_paragraphs"]
        # Stable hash sample without using predicted labels, including noncausal paragraphs.
        for paragraph in sorted(paragraphs, key=digest)[:12]:
            cid = digest([row["id"], paragraph])
            cases.append(
                {
                    "id": cid,
                    "kind": "causal_language",
                    "ticker": row["ticker"],
                    "accession": row["accession"],
                    "split": split,
                    "text": paragraph,
                    "source_url": row["source_url"],
                    "source_sha256": row["capture_sha256"],
                    "snapshot_id": row["id"],
                    "available_at": utc(row["available_at"]).isoformat(),
                    "as_of": cutoff.isoformat(),
                }
            )
            predictions[cid] = predicted.get(paragraph, "NO_CAUSAL_CLAIM")
        for item in current["segments"]:
            cid = digest([row["id"], item["segment"], item["metric"]])
            cases.append(
                {
                    "id": cid,
                    "kind": "segment_comparison",
                    "ticker": row["ticker"],
                    "accession": row["accession"],
                    "split": split,
                    "source_url": row["source_url"],
                    "source_sha256": row["capture_sha256"],
                    "snapshot_id": row["id"],
                    "available_at": utc(row["available_at"]).isoformat(),
                    "as_of": cutoff.isoformat(),
                    "concept": item["concept"],
                    "dimensions": item["dimensions"],
                    "current_locator": item["current"]["fact_id"],
                    "prior_locator": item["prior"]["fact_id"],
                }
            )
            predictions[cid] = {
                k: item[k] for k in ("current", "prior", "delta", "unit", "period_kind")
            }
    return {
        "cases": cases,
        "predictions": predictions,
        "status": "AWAITING_INDEPENDENT_LABELS",
        "extractor": "inline-segment-attribution-v1",
        "as_of": cutoff.isoformat(),
    }


def evaluate(pack, labels):
    cases = {c["id"]: c for c in pack["cases"] if c["split"] == "holdout"}
    votes: dict = {}
    for label in labels:
        cid = label["case_id"]
        if cid not in cases:
            raise ValueError("Unknown or non-holdout case")
        reviewer = label["reviewer"].strip().casefold()
        if (
            not reviewer
            or reviewer in {"codex", "agent", pack["extractor"].casefold()}
            or label.get("independent_of_extractor") is not True
        ):
            raise ValueError("Independent human reviewer declaration required")
        if (
            not label.get("reason", "").strip()
            or label.get("source_sha256") != cases[cid]["source_sha256"]
        ):
            raise ValueError("Source hash and rationale required")
        reviewed = datetime.fromisoformat(label["reviewed_at"])
        if reviewed.tzinfo is None or not datetime.fromisoformat(
            cases[cid]["available_at"]
        ) <= reviewed <= datetime.now(UTC):
            raise ValueError("Invalid review time")
        if cases[cid]["kind"] != "causal_language" or label["label"] not in CLASSES:
            raise ValueError("Segment numeric annotations require separate manual adjudication")
        group = votes.setdefault(cid, {})
        if reviewer in group:
            raise ValueError("Duplicate reviewer vote")
        group[reviewer] = label["label"]
    eligible = {cid: v for cid, v in votes.items() if len(v) >= 2}
    consensus = {
        cid: next(iter(v.values())) for cid, v in eligible.items() if len(set(v.values())) == 1
    }
    total = sum(c["kind"] == "causal_language" for c in cases.values())
    scored = len(consensus)
    return {
        "status": "COMPLETE" if scored == total and total else "PENDING_LABELS_OR_ADJUDICATION",
        "holdout_language_cases": total,
        "consensus_cases": scored,
        "disagreements": sum(len(set(v.values())) > 1 for v in eligible.values()),
        "accuracy_on_consensus": sum(
            pack["predictions"][cid] == gold for cid, gold in consensus.items()
        )
        / scored
        if scored
        else None,
        "market_prediction_accuracy": None,
        "segment_validation": "PENDING_MANUAL_ADJUDICATION",
        "note": "Language classification only; no causal-effect or market accuracy claim",
    }


def main():
    import argparse

    from engine.db import database

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    engine = database()
    try:
        with engine.connect() as conn:
            pack = packet(conn, datetime.now(UTC))
        args.output.mkdir(parents=True, exist_ok=True)
        for name, value in [
            ("blind-cases.json", pack["cases"]),
            ("sealed-predictions.json", pack),
            ("labels.json", []),
        ]:
            path = args.output / name
            if path.exists():
                raise ValueError("Use a new output directory; never overwrite labels")
            path.write_text(json.dumps(value, ensure_ascii=False, indent=2), encoding="utf-8")
        print(
            json.dumps(
                {
                    "cases": len(pack["cases"]),
                    "status": pack["status"],
                    "evaluation": evaluate(pack, []),
                }
            )
        )
    finally:
        engine.dispose()


if __name__ == "__main__":
    main()
